using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Geometry.Lorentz;

internal sealed class PenroseCarterCausalCompactification4DDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Geometry/Lorentz/PenroseCarterCausalCompactification4D.";
    private static readonly LibraryNoteRef Penrose =
        LibraryNoteRef.Create("D5/L/Observer/penrose1963asymptotic");
    private static readonly LibraryNoteRef Kruskal =
        LibraryNoteRef.Create("D5/L/Observer/kruskal1960extension");
    private static readonly LibraryNoteRef GibbonsHawking =
        LibraryNoteRef.Create("D5/L/Observer/gibbonshawking1977horizons");

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Minkowski and de Sitter conformal boundaries, extended Schwarzschild coordinates, and sharp proper time.",
        H("Conformal infinity and the Kruskal extension"),
        Blocks(
            Paragraph(Text("The Einstein cylinder has unit spatial radius. The Minkowski factor is the sum of the compactified time and radius cosines. The de Sitter conformal clock runs across an interval of length pi, and the Kruskal coordinates use null product below one to parametrize positive radius.")),
            Entry("minkowski-image", "minkowski_image", "Exact image inequalities",
                "For nonnegative physical radius the compactified radius is nonnegative and its sum with absolute compactified time is less than pi.", Penrose),
            Entry("conformalfactor-pos", "conformalFactor_pos", "Positive interior conformal factor",
                "The sum of the time and radius cosines is strictly positive where compactified radius is nonnegative and its sum with absolute time is less than pi."),
            Entry("minkowski-inverse", "minkowski_inverse", "Inverse in the physical coordinates",
                "The sine over the sum of cosines formulas recover the original time and radius from the forward map."),
            Entry("minkowski-onto", "minkowski_onto", "Inverse in the compactified coordinates",
                "In the diamond the inverse radius is nonnegative and applying the forward map to the two inverse quantities recovers the compactified point."),
            Entry("minkowski-image-iff", "minkowski_image_iff", "Image characterized by the diamond",
                "The stated diamond inequalities characterize all pairs arising from a real time and nonnegative radius."),
            Entry("minkowski-coordinate-derivatives", "minkowski_coordinate_derivatives", "Arctangent coordinate derivatives",
                "Differentiable physical curves have compactified derivatives given by the sum and difference of the two null coordinate derivatives, each with its arctangent denominator."),
            Entry("minkowski-metric-pullback", "minkowski_metric_pullback", "Four-dimensional metric identity",
