            Entry("desitter-boundary-induced-positive", "deSitter_boundary_induced_positive", "Positive boundary metric",
                "In regular spherical coordinates the induced quadratic form on a nonzero spatial tangent vector is positive."),
            Entry("desitter-boundary-limits", "deSitter_boundary_limits", "Limits of the de Sitter conformal clock",
                "The clock approaches minus pi over two toward the past and pi over two toward the future."),
            Entry("desitterscale-derivative", "deSitterScale_derivative", "Closed de Sitter scale derivative",
                "The derivative of the radius times the hyperbolic cosine of proper time over radius is the corresponding hyperbolic sine."),
            Entry("desitter-friedmann", "deSitter_friedmann", "Closed Friedmann identity",
                "For positive de Sitter radius the Hubble square and reciprocal scale square sum to the reciprocal radius square."),
            Entry("desitter-conformalfactor-pos", "deSitter_conformalFactor_pos", "Positive de Sitter factor",
                "Cosine is positive in the open conformal time interval."),
            Entry("causal-angular-displacement", "causal_angular_displacement", "Causal angular travel bound",
