            Entry("desitter-causal-horizon-dichotomy", "desitter_causal_horizon_dichotomy", "Observer diamond for the full lifetime",
                "A point of nonnegative polar angle is reachable to and from finite polar-zero observer times inside the conformal interval precisely when its absolute conformal time plus its polar angle is less than pi over two.", GibbonsHawking),
            Entry("kruskalf-deriv-and-strict-anti", "kruskalF_deriv_and_strict_anti", "Kruskal radial profile",
